test('merge treats same-id title or tag differences as conflicts', () => {
  const base = snapshotOf([
    { id: 'a', title: 'A', body: 'body text', tags: ['one'] },
  ]);
  const changedTitle = snapshotOf([{ id: 'a', title: 'A2', body: 'body text', tags: ['one'] }]);
