    assert.deepEqual(workspace.exportJSON(), base);
  }
});

test('merge title moves: a moved-away title is free, a moved-into title collides', () => {
  // x renames T -> T2; newcomer y takes the freed title T. Only x conflicts
  // (its content changed); y inherits the vacated title legitimately.
  const base = snapshotOf([{ id: 'x', title: 'T', body: 'body text', tags: [] }]);
  const freed = snapshotOf([
    { id: 'x', title: 'T2', body: 'body text', tags: [] },
    { id: 'y', title: 'T', body: 'newcomer body', tags: [] },
  ]);
  const freeing = new Workspace();
  freeing.importJSON(base, { mode: 'replace' });
  assert.throws(
    () => freeing.importJSON(freed, { mode: 'merge' }),
    (error) => error.code === 'IMPORT_CONFLICT' && error.ids.length === 1 && error.ids[0] === 'x',
  );

  // x renames T -> T2 while newcomer y also claims T2: both conflict.
  const blocked = snapshotOf([
    { id: 'x', title: 'T2', body: 'body text', tags: [] },
    { id: 'y', title: 'T2', body: 'newcomer body', tags: [] },
  ]);
  // That incoming snapshot is itself illegal (duplicate normalized titles),
  // so model the real collision with an untouched existing owner instead:
  const baseTwo = snapshotOf([
    { id: 'x', title: 'T', body: 'body text', tags: [] },
    { id: 'z', title: 'T2', body: 'existing owner', tags: [] },
  ]);
  const renameIntoOwner = snapshotOf([{ id: 'x', title: 'T2', body: 'changed body', tags: [] }]);
  const workspace = new Workspace();
  workspace.importJSON(baseTwo, { mode: 'replace' });
  assert.throws(
    () => workspace.importJSON(renameIntoOwner, { mode: 'merge' }),
    (error) => error.code === 'IMPORT_CONFLICT' && error.ids.length === 1 && error.ids[0] === 'x',
  );
  assert.deepEqual(workspace.exportJSON(), baseTwo);

  void blocked;
});

test('merge succeeds when an unchanged id frees nothing but a new title is unique', () => {
  const base = snapshotOf([{ id: 'x', title: 'T', body: 'body text', tags: [] }]);
  const additions = snapshotOf([{ id: 'y', title: 'U', body: 'other body', tags: [] }]);
  const workspace = new Workspace();
  workspace.importJSON(base, { mode: 'replace' });
  const result = workspace.importJSON(additions, { mode: 'merge' });
  assert.deepEqual(result.documents.map((document) => document.id), ['x', 'y']);
});

